import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { ContextPruningTracker } from "./src/core/context-pruning/tracker.ts";
import { recoverablePrune } from "./src/core/context-pruning/recovery.ts";
import type { ToolRecord } from "./src/core/context-pruning/types.ts";

const root = mkdtempSync(join(process.cwd(), ".pruning-check-"));
afterAll(() => rmSync(root, { recursive: true, force: true }));
const output = "検索結果 🧪\\n".repeat(300);
const args = { query: "example" };
const record = (callId: string, originalOutput = output, prunedOutput: string | null = null): ToolRecord => ({
  callId, toolName: "code_search", args, originalOutput, prunedOutput, timestamp: 0,
});
const run = (tracker: ContextPruningTracker, call: string, text = output, scope = "session") =>
  tracker.process(call, "code_search", args, text, recoverablePrune(root, scope, call, text));

test("final emitted recovery text and original survive reload with byte statistics", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "first");
  const second = run(tracker, "second");
  expect(readFileSync(second.recoveryPath!, "utf8")).toBe(output);
  expect(tracker.getHistory()[1].prunedOutput).toBe(second.output);
  expect(tracker.getHistory()[1].originalOutput).toBe(output);
  expect(second.bytesSaved).toBe(Buffer.byteLength(output) - Buffer.byteLength(second.output));
  const saved = JSON.parse(JSON.stringify(tracker.getHistory()));
  const reloaded = new ContextPruningTracker(root);
  reloaded.loadHistory(saved);
  expect(reloaded.getStats()).toEqual(tracker.getStats());
  expect(reloaded.getStats()).toEqual({ totalCalls: 2, prunedCalls: 1,
    totalBytesSaved: second.bytesSaved,
    estimatedContextBytes: Buffer.byteLength(output) + Buffer.byteLength(second.output) });
  expect(run(reloaded, "third").output).toContain("callId: first");
});

test("evicting the full baseline causes a new full result", () => {
  const tracker = new ContextPruningTracker(root, 2);
  run(tracker, "first");
  run(tracker, "second");
  expect(run(tracker, "third").output).toContain("callId: first");
  expect(run(tracker, "fourth").modified).toBe(false);
  expect(run(tracker, "fifth").output).toContain("callId: fourth");
});

test("selects latest matching full result, skipping shortened and differing output", () => {
  const tracker = new ContextPruningTracker(root);
  tracker.loadHistory([record("old"), record("latest"), record("shortened", output, "pointer"), record("different", "other")]);
  expect(run(tracker, "new").output).toContain("callId: latest");
  tracker.loadHistory([record("shortened", "original", output)]);
  expect(run(tracker, "new-full").modified).toBe(false);
});

test("recovery rejection records a full baseline and zero savings", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "first");
  const rejected = run(tracker, "rejected", output, "");
  expect(rejected).toEqual({ output, modified: false, bytesSaved: 0 });
  expect(tracker.getHistory()[1].prunedOutput).toBeNull();
  expect(tracker.getStats()).toEqual({ totalCalls: 2, prunedCalls: 0, totalBytesSaved: 0,
    estimatedContextBytes: 2 * Buffer.byteLength(output) });
  expect(run(tracker, "next").output).toContain("callId: rejected");
});

test("recovery rejects small outputs and storage failures", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "small-first", "tiny");
  expect(run(tracker, "small-second", "tiny").modified).toBe(false);
  expect(tracker.getHistory()[1].prunedOutput).toBeNull();
  const blocked = join(root, "file");
  writeFileSync(blocked, "not a directory");
  const other = new ContextPruningTracker(root);
  other.process("first", "code_search", args, output);
  const failed = other.process("failure", "code_search", args, output, recoverablePrune(blocked, "session", "failure", output));
  expect(failed.modified).toBe(false);
  expect(other.getHistory()[1].prunedOutput).toBeNull();
  expect(other.getStats().totalBytesSaved).toBe(0);
});

test("different arguments and outputs do not deduplicate", () => {
  for (const tool of ["code_search", "Grep", "Glob", "Read"]) {
    const tracker = new ContextPruningTracker(root);
    const originalArgs = { pattern: "x", path: "missing", query: "x", mode: "full" };
    tracker.process("first", tool, originalArgs, output);
    expect(tracker.process("changed-args", tool, { ...originalArgs, mode: "summary" }, output).modified).toBe(false);
    expect(tracker.process("changed-output", tool, originalArgs, output + "new").modified).toBe(false);
    expect(tracker.process("repeat", tool, originalArgs, output).output).toContain("callId: first");
  }
});

test("side-effecting tools remain unchanged", () => {
  for (const tool of ["Bash", "Write", "Edit", "mcp__aide__memory_add", "task_update"]) {
    const tracker = new ContextPruningTracker(root);
    tracker.process("first", tool, args, output);
    expect(tracker.process("second", tool, args, output)).toEqual({ output, modified: false, bytesSaved: 0 });
  }
});

test("dedup without recovery also preserves its emitted output", () => {
  const tracker = new ContextPruningTracker(root);
  tracker.process("first", "code_search", args, output);
  const second = tracker.process("second", "code_search", args, output);
  expect(tracker.getHistory()[1].prunedOutput).toBe(second.output);
  expect(tracker.process("third", "code_search", args, output).output).toContain("callId: first");
});
